        // Meta (Oculus) app secret, used ONLY to validate a headset login's nonce with Meta (see
        // MetaNonce). Deliberately not a literal here: read from the META_APP_SECRET environment
        // variable, else the first non-comment line of Data/meta_app_secret.txt. Empty = Meta
        // logins cannot be verified, and cached (password-free) Quest logins answer 500 rather than
        // trusting the client; password logins still work, they just never link the headset.
        public static string MetaAppSecret => _metaAppSecret ??= LoadMetaAppSecret();
        private static string? _metaAppSecret;
        private static string LoadMetaAppSecret()
        {
            string? env = Environment.GetEnvironmentVariable("META_APP_SECRET");
            if (!string.IsNullOrWhiteSpace(env)) return env.Trim();
            try
            {
                string path = Path.Combine(Environment.CurrentDirectory, "Data", "meta_app_secret.txt");
                if (File.Exists(path))
                    foreach (var raw in File.ReadAllLines(path))
                    {
                        var line = raw.Trim();
                        if (line.Length > 0 && !line.StartsWith("#")) return line;
                    }
            }
            catch (Exception ex) { Console.WriteLine($"[meta] could not read Data/meta_app_secret.txt: {ex.Message}"); }
            Console.WriteLine("[meta] no app secret configured - Meta logins cannot be verified (set META_APP_SECRET or Data/meta_app_secret.txt)");
            return "";
        }
        // The key every game / website / Photon token is signed with. It was ONLY this string in
        // the source, so anyone holding a copy of the code could sign a token as any account
        // (developers included). Set CAMPUS_KEY (env) or Data/jwt_key.txt to rotate it; CampusNet
        // must be given the SAME value (CAMPUS_KEY / CAMPUSNET_JWT_KEY) or Photon logins fail.
        // Rotating signs everyone out once (their stored refresh tokens still work).
        public static string Key = LoadSigningKey();
        private const string BuiltInKey = "REDACTED";
        private static string LoadSigningKey()
        {
            var env = Environment.GetEnvironmentVariable("CAMPUS_KEY");
            if (!string.IsNullOrWhiteSpace(env)) { Console.WriteLine("[security] token signing key: from CAMPUS_KEY"); return env.Trim(); }
            try
            {
                var path = Path.Combine(Environment.CurrentDirectory, "Data", "jwt_key.txt");
                if (File.Exists(path))
                {
                    var k = File.ReadAllText(path).Trim();
                    if (k.Length >= 32) { Console.WriteLine("[security] token signing key: from Data/jwt_key.txt"); return k; }
                    Console.WriteLine("[security] Data/jwt_key.txt is shorter than 32 characters - ignored");
                }
            }
            catch (Exception ex) { Console.WriteLine($"[security] could not read Data/jwt_key.txt: {ex.Message}"); }
            Console.WriteLine("[security] WARNING: token signing key is the BUILT-IN default from the source code - set CAMPUS_KEY or Data/jwt_key.txt");
            return BuiltInKey;
        }
        public static string VALID_STATUS_KEY = "REDACTED";

