        // and refuses to join their rooms - and player cards fail to render. It was hardcoded to
        // "20250731.01" (a build newer than the 20250718.01 client), so EVERYONE showed mismatched.
        // Update this one constant whenever the client build changes.
        public static string PresenceAppVersion = "20250718.01";

