        // NOT wrapped into a joinable room (a room that only freezes the game is worse than none).
        // Bump this if a higher-version room turns out to load in-game.
        public static int ClientMaxRoomPersistenceVersion = 33;

        // A profile's room lists (ownedby / showcase) return every room the account owns. After a bulk
