        // reference (github.com/recflare/server, apps/api custom-avatar-items-db.ts) serves the
        // very same records and the same Unity bundles from its CDN. False = hide it again.
        public static bool ServeFirstPartyClothing = true;

        // The CDN base the name server (/ns) hands the client. It MUST be on a different host
        // from every API service. The 2025 client's RecNet HTTP client (CBACIMLIBPF) builds a
        // "no BestHTTP cache" host set from the service map - every service's host except
        // Images (6), CDN (7) and StringsCDN (26) - and any download from a host in that set is
        // sent with DisableCache. The avatar-bundle loader (Addressables provider ->
        // CBACIMLIBPF.PNKGBHGAHHH) only works THROUGH the cache: it hands on the response's
        // BestHTTP CacheFileInfo, which is null when the download was not cached, and that is
        // the NullReferenceException behind every "Unable to load asset bundle from:
        // avatar/..." - with the CDN on camprec.net (the API host) no bundle ever cached.
        // The reference gives every service its own subdomain (cdn.recflare.net), which is why
        // the same bundles load there.
        // The URL MUST be https: an http:// CDN makes the client throw "Invalid URI scheme"
        // constructing the boot-time CDN request (/config/<guid>) and the game stops at
        // "Launch validation failed" (tried 2026-09-26 with http://50.114.179.17:8080/cdn).
        // So a separate host needs its own name AND a valid certificate: cdn.camprec.net
        // (gameauthcdn.ddns.net before 2026-10-07), plus its own Caddy site block (UploadUpdate.bat
        // adds the block). /ns only advertises CdnBaseUrl once CdnHost's probe has seen that
        // host resolve to this server and answer over https with a valid certificate; until
        // then it hands out CdnFallbackUrl (the API host - boots fine, bundles don't load).
        public static string CdnBaseUrl = "https://cdn.camprec.net/cdn";
        public static string CdnFallbackUrl = "https://camprec.net/cdn";

        // The site / game host. (The Discord / Spotify / social sign-in CALLBACKS stay on gameauth.ddns.net - that is what is registered
        // with those services - so after one, the player is sent back to this host: its website cookie lives here.)
        public const string SiteUrl = "https://camprec.net";

        // When ON, /ns always hands out CdnFallbackUrl (the API host) regardless of what the
        // server-side probe sees. The probe only measures what THIS server can reach: some
        // players' DNS still can't resolve cdn.camprec.net (slow propagation, stale ISP
        // caches, carrier-grade NAT), and when it fails on their end the client throws the
        // "summer" NS-validation error at launch - the server never sees them. Flip this on
        // from the admin panel the moment "error code summer" reports come in; it stops the
        // breakage for everyone at the cost of clothing bundles not caching (which is a visual
        // thing, not a connection thing). Turn it back off once the CDN host is reliable again.
        public static bool ForceCdnFallback = false;

        // A report filed in-game by a developer or moderator times the reported player out for
        // this long (APIController.CreatePlayerReport). Underage reports make them junior instead.
        public static int StaffReportTimeoutSeconds = 3600;

        // XP one game reward pays. Was the reference's 5, on the real curve (Progress.LEVEL_REQUIRED_XP)
        // where the last ten levels cost 1080 XP EACH - 216 rewards per level. 25 keeps the real
        // curve (the client renders its bar against it, so the curve itself must not change) and
        // makes every level five times faster: an early level is one game, a top level ~45.
        public static int GameRewardXp = 25;

        // Leaderboard plausibility gate, REC ROOM ORIGINAL rooms only (LeaderboardGuard). A score
        // that climbs faster than MaxGainPerSecond, or by more than MaxGainPerDay in one UTC day,
        // is refused and filed as a system Cheating report. Player-made rooms are never gated.
        public static bool LeaderboardGuardEnabled = true;
        public static int  LeaderboardMaxGainPerSecond = 1000;
        public static long LeaderboardMaxGainPerDay = 250_000;

        // Rooms whose boards are RACE TIMES in milliseconds, lowest wins (Stunt Runner = 40). The
        // client still asks for them with SortAscending=false, so the server has to know:
        //   * an unranked GetPlayerRank answers Score int.MaxValue (the worst time). With the
        //     {Score:0} every other room gets, a 0 ms best was "stored" that no run could beat, so
        //     nothing was written and every run said "new best"; JSON null made the client's HTTP
        //     layer throw "Response was empty" - no write either. The game's best-time callback
        //     (`best = result.Score; if (best <= 0) best = int.MaxValue`) takes int.MaxValue as-is;
        //   * the boards are ordered fastest first whatever the body asks for;
        //   * the gain caps above don't apply (a first 4-minute run is 240,000 "points"); a time
        //     under LeaderboardMinTimeMs is refused as impossible instead.
        public static readonly HashSet<ulong> LeaderboardLowestWinsRooms = new() { 40 };
        public static int LeaderboardMinTimeMs = 5000;

        // Overall boards the SERVER keeps as the sum of a room's course boards (LeaderboardDB.
        // RecomputeTotal). Stunt Runner: sc1-sc6 are the six courses, sc7 the overall time. The
        // room itself only posts sc7 for a player who ran all six in one event, so anyone who
        // missed a course that event never got an overall time; this adds up their best on each.
        public static readonly Dictionary<ulong, (int Total, int[] Parts)> LeaderboardTotalChannels = new()
        {
            [40] = (7, new[] { 1, 2, 3, 4, 5, 6 }),
        };

        // Rooms a player may pin to the showcase at the top of their profile (PUT showcase).
        public static int ShowcaseCap = 12;

        // Progression (level-up) rewards: the client draws those icons itself. Its
        // ProgressionRewardLevelModelController/RewardIconImageImpl picks a built-in sprite from a
        // `rewardIndex` and only falls back to a RecNetRawImage when the server names one - so
        // naming ours overrides the game's own art with a flat PNG. Sending no name lets the
        // embedded icon win. (Game-reward DROPS are the opposite: the picker/gift-box tile really
        // does render blank without a ThumbnailImageName, so QuestRewards still sends one.)
        public static bool UseClientProgressionIcons = true;

        // Token drops on the reward picker and token gift boxes: true = name no picture and let the
        // client draw its own built-in token art (what the reference does); false = our custom
        // LevelRewardImage (campus_tokens.png). Flip back to false if a token card ever shows blank.
        public static bool UseClientCurrencyImages = true;

        // The picture on every Level Rewards tile and on token gift boxes - a file name under
        // Data/Images, served as /img/<name>. Gameconfigs.json's Lifecycle.PSF.Progression.RewardMap
        // and UnknownRewardImage are rewritten to this on the way out (APIController.Gameconfigs),
        // so changing the picture is this one line, not fifty JSON entries.
        public static string LevelRewardImage = "campus_tokens.png";

        // Log each DISTINCT request header name once per process (Middleware/Log.cs). Cheap, and it
        // is how you find out whether this client signs its requests at all rather than assuming.
        public static bool LogNewRequestHeaders = true;

        // -----------------------------
        // Account creation / lock  (see AccountLock.cs + AuthController grant handling)
        // -----------------------------
        // Accounts are made in-game on first launch (InGameAccountCreation) or on the website
        // (SiteController /api/site/register). On the first in-game login an account is bound to
        // that Steam id AND that device, and can never be signed in from another Steam/device
        // afterwards - the anti-alt lock. A device may host one of each origin
        // (MaxAccountsPerDevice below).
        public static bool EnforceAccountLock = true;

        // These accounts are exempt from the lock so they can share one Steam/device (the
        // owner's own test accounts). Matched by CURRENT username at startup and pinned to the
        // account ids they resolve to (AccountLock.ResolveExemptions), so renaming a different
        // account to one of these later does NOT grant it the exemption.
        public static string[] LockExemptUsernames = { "Coach", "Kyle", "Importer" };

        // The account lock caps how many DEVICES one account may sign in from, and limits them to
        // one per device class (PC vs Quest/VR headset) - i.e. a player gets one PC and one Meta
        // Quest, nothing more. The spoofable platform_id (Steam/Meta id) is NO LONGER used to gate
        // a login - it's recorded for reference only - so lying about it gains nothing; the lock
        // now hangs on the device id + platform instead. Exempt accounts (Coach/Kyle) are
        // unaffected. Raise this only if you deliberately want to allow more devices.
        public static int MaxDevicesPerAccount = 2;

        // A new device of a class the account already has (a second PC, a second headset) may
        // take the slot once the old device has not signed in for this long. Keeps "one PC at a
        // time" while letting a player move to a new PC / reinstall without an admin.
        public static int DeviceReplaceAfterMinutes = 60;

        // How many accounts one DEVICE (and, on PC, one Steam id) may host: one made by the game on
        // the client's first launch plus one made on the website, so a player can play either way
        // and switch between them from the client's account picker. The two slots are by ORIGIN
        // (player_data.CreatedInGame): a second in-game creation on the device is refused, and so
        // is signing in a second website account. Accounts older than the origin flag fit either
        // slot. Exempt accounts (LockExemptUsernames) are never counted. 1 = the old one-per-device.
        public static int MaxAccountsPerDevice = 2;

        // false = the two slots above are by COUNT only: any two accounts (in-game creation is
        // still limited to one per device). true = one made in-game + one made on the website.
        // Off, because players with one website account on a headset were refused their second.
        public static bool DeviceSlotsByOrigin = false;

        // "X is online" goes to a player's friends at most once per this many minutes - the client
        // posts player/login on every reconnect, not only at launch.
        public static int FriendOnlineNoticeCooldownMinutes = 30;

        // Website signup limits. Layered, so a household / school / mobile-carrier network (many
        // real people behind ONE address) is not locked out for a week by the first person who
        // signs up, while a bot is capped far harder than the old one-per-IP-per-7-days rule:
        //   - per IP:      SignupsPerIpPerDay in any rolling 24 h, SignupsPerIpPerWeek in 7 days
        //   - per /24:     SignupsPerSubnetPerDay (IPv4 block; catches a bot rotating addresses
        //                  inside one range) - generous, shared networks share the exact IP anyway
        //   - global:      SignupsPerHour across ALL addresses. This is the real mass-creation
        //                  stop: proxies rotate IPs, they cannot rotate the clock. Raise it if a
        //                  genuine launch spike trips it (the log says so).
        // Quest "remember me". A headset on the no-Meta / Meta-fallback path has no platform
        // identity the server can verify (Meta only hands one over once Data Use Checkup approves
        // the app), so it would have to type its password every launch. With this on, the
        // headset's per-install DEVICE id - the same value the one-PC-one-Quest account lock
        // already binds on the first password login - is accepted as the cached-login credential
        // for that account. A player types their password once per headset; after that the picker
        // offers the account and cached_login redeems it. Device ids are random per install and
        // never shown to other players; this is the same trust the device lock already places in
        // them. Real, Meta-verified identities always take precedence when present.
        public static bool QuestDeviceCachedLogin = true;

        // A headset with NO remembered account used to be handed a placeholder cached-login entry
        // (accountId 0, requirePassword=true) to reach the password screen. The 2025 client shows
        // that placeholder as an account tile - "@Player0: Password required" - i.e. a fake account.
        // With this OFF the picker is answered [] instead: the client shows its own empty "Switch
        // account" screen, and the player presses + to log in with their Campus username and
        // password (an auto create_account attempt is refused with a message pointing at the
        // website). Turn back ON only if a brand-new headset cannot reach a login form that way.
        public static bool QuestLoginPlaceholder = true;

        // Seconds to hold the RewardSelectionReceived push after a game-reward request. The PC
        // (screen-mode) client tears the reward picker down ~2 s after it opens when the push
        // lands in the same breath as the end-of-game UI; letting that settle first is the
        // experiment. 0 = push immediately (what Quest has always had).
        public static double RewardSelectionPushDelaySeconds = 0;

        // false = every activity's reward picker offers TOKENS (10..1000, in that activity's own
        // box) instead of items from quest-rewards.json. The item tables reference UGC/outfit
        // bundles the CDN no longer has, so items render blank on PC; tokens always render and pay.
        public static bool RewardItemsEnabled = false;

        // How many of the picker's three cards are WATCH-STORE CLOTHING the player does not own yet
        // (2 to 4 stars = store Rarity 10/20/30). The rest are tokens. The Watch rows are the ones the
        // client already draws from its own item db, so they render (the quest-rewards.json items do
        // not). 0 = tokens only; 3 = all clothing (tokens only when the player owns every candidate).
        public static int RewardWatchClothingCards = 2;

        // UGC custom avatar items are served only if they were CREATED on or before this date -
        // the day after the game clients' build (PC + Quest 20250718.01). Anything exported from
        // the live game after that carries config fields / assets those clients can't read (the
        // 2025-08 "Roomie's Quest Sword" with its d.d.et key aborted the whole locker pass), so
        // newer items and newer saves are dropped at catalog load. Null = serve everything.
        public static DateTime? CustomItemCreatedCutoffUtc = new DateTime(2025, 7, 19, 23, 59, 59, DateTimeKind.Utc);

        // Seconds added to a reward selection's CreatedAt. 0 = the truth. This was 300, a workaround
        // for the PC client auto-picking card 1 within seconds; the real cause was the heartbeat's
        // serverTime (Unix seconds, read by the client as DateTime ticks = year 0001), which made
        // the client's "time left" overflow int32 negative on x86. Fixed at the source in
        // HeartbeatDB.Heartbeat.serverTime, so CreatedAt no longer needs shifting.
        public static double RewardSelectionCreatedAtOffsetSeconds = 0;

        // Let a brand-new HEADSET make its account in-game. The 2025 client's first-launch flow on
        // Quest posts grant_type=create_account (it wants to mint an account for the new platform
        // user, as the real RecNet does); refusing it showed "error code 3" and left the player with
        // no way in short of the website. Protected exactly like the website signup: the per-IP /
        // per-subnet / global signup caps, one account per device, and the sentinel platform id is
        // never stored. PC stays website-only (a PC player has the site one tab away).
