        public static bool AdminTestNewAccountFlow =>
            System.IO.File.Exists(System.IO.Path.Combine(Environment.CurrentDirectory, "Data", "admin_test_newaccount.txt"));

        // Per-ADDRESS caps, sized for SHARED addresses.
        //
        // These were 1/day, 2/week and 4 per /24 - written for the idea that one IP is one
        // person. It is not. A mobile carrier puts thousands of players behind one CGNAT address,
        // a school or a dorm block puts a whole building behind one, and a house with two Quests is
        // two players on one IP. At 1/day the SECOND of them was refused for 24 hours - "Code 3" -
        // and a VPN fixed it by handing them a fresh address, which is how we know it was these.
        //
        // The anti-alt job these were doing is done better by the one-account-per-DEVICE rule
        // (MaxAccountsPerDevice, checked right after this in AuthController): a device can only
        // ever register one account whatever address it uses. What is left for the IP caps is bulk
        // bot creation, and the global breaker below (SignupsPerHour + SignupBurstDistinctNetworks)
        // is the thing that catches that. So these only need to be high enough that a shared
        // network is never the reason a real player cannot get in.
        //
        // The 2026-09-12 note ("3/day let one person make three accounts in 90 s") predates the
        // device rule; that person would now be stopped at their second account by the device
        // binding regardless of what this number says.
        public static int SignupsPerIpPerDay = 12;
        public static int SignupsPerIpPerWeek = 40;
        public static int SignupsPerSubnetPerDay = 60;

        // The global hourly ceiling, and how few distinct networks an hour must come from before
        // reaching that ceiling counts as mass creation rather than growth. BOTH have to be true
        // for the breaker to fire - see PlayerDB.CheckSignupLimit.
        //
        // 15/hour was the old value and in practice it was a growth cap: it locked every new
        // player out for the rest of the hour, on every platform, while the per-IP and per-subnet
        // caps - the ones that actually target abuse - never fired once. An attacker bound to
        // 1/IP/day and 4 per /24 per day needs ~38 distinct /24s to reach 150 in an hour, and if
        // they are that spread out the distinct-network test lets it through deliberately: at that
        // point the per-network caps are the right defence and a global stop only punishes real
        // players.
        public static int SignupsPerHour = 150;
        public static int SignupBurstDistinctNetworks = 12;
        // IPs that bypass the signup rate limit (e.g. the owner's own IP for making test
        // accounts). Loopback is always exempt regardless of this list.
        public static System.Collections.Generic.HashSet<string> SignupExemptIps
            = new System.Collections.Generic.HashSet<string>();

        // -----------------------------
        // Traffic guard  (see Middleware/TrafficGuardMiddleware.cs) - flood / DoS defence
        // -----------------------------
        // Master switch for the per-IP rate limiting below. Turn OFF only to debug a
        // false-positive throttle; the Kestrel connection/timeout caps in Program.cs stay
        // on regardless.
        public static bool TrafficGuardEnabled = true;

        // GENERAL flood ceiling: how many requests ONE IP may make per window before it is
        // 429'd. Deliberately generous - normal play bursts hundreds of image/presence calls,
        // and several players behind one household NAT / CGNAT share a single IP - so this
        // only bites an actual flood, never real traffic. Keyed on the TRUSTWORTHY client IP
        // (the LAST X-Forwarded-For entry Caddy appends), so a spoofed XFF cannot rotate past
        // it. Loopback is always exempt.
        public static int FloodWindowSeconds = 10;
        public static int FloodMaxPerWindow  = 1200;   // ~120 req/s sustained per IP

        // AUTH ceiling: the credential endpoints (/Auth/connect/token, /api/site/login). Tight,
        // because these are the brute-force / credential-stuffing surface and a real client only
        // signs in a handful of times. Exceeding it returns 429 - this is what stops someone
        // hammering the token endpoint to guess passwords or farm bearer tokens.
        // 20 per 5 minutes was too tight: a single client signs in, refreshes and re-signs in
        // several times per session, several players share one household / CGNAT address, and a
        // 429'd client retries every few seconds. Brute force is LoginGuard's job (it counts
        // FAILED logins); this is only the flood ceiling.
        public static int AuthWindowSeconds = 300;     // 5 minutes
        public static int AuthMaxPerWindow  = 90;

        // Brute-force lockout (see LoginGuard.cs): after this many FAILED logins from one IP inside
        // the window, that IP is blocked from the login endpoint for LoginFailBlockMinutes. Only
        // FAILURES count - a successful login clears the counter. Enforced in TrafficGuardMiddleware.
        public static bool LoginFailBlockEnabled  = true;
        public static int  LoginFailBlockThreshold = 3;   // failed attempts before the block
        public static int  LoginFailBlockMinutes   = 5;   // how long the IP stays blocked
        public static int  LoginFailWindowSeconds  = 300; // window the failures are counted in

        // Hard caps on the credential fields, so a bot/attacker can't post a megabyte username or
        // control characters at the login/auth path (defence-in-depth; the DB is LiteDB/NoSQL so
        // there is no SQL to inject, but oversized/garbage input is still rejected early).
        public static int MaxUsernameLength = 64;
        public static int MaxPasswordLength = 256;

        // Hard per-request body cap (bytes), server-wide. Blocks the "POST a huge body to
        // balloon memory" vector. 30 MB matches Kestrel's historical default so it changes
        // nothing for real room/image uploads; the token endpoint bounds itself far tighter.
        public static long MaxRequestBodyBytes = 30L * 1024 * 1024;

        // Global ceiling on concurrent TCP connections Kestrel will hold open at once (normal
        // sockets + upgraded/WebSocket sockets each get this). Caps socket/memory growth under
        // a connection flood so the process cannot be driven OOM by opening endless sockets.
        public static long MaxConcurrentConnections        = 2000;
        public static long MaxConcurrentUpgradedConnections = 2000;

        // YouTube fetch (admin Videos tab, api/server/YoutubeFetch.cs): only videos whose uploader released them under Creative Commons.
        // The Data API key is NOT a literal here: env YOUTUBE_API_KEY, else the first non-comment line of Data/youtube_api_key.txt.
        // Empty = the feature refuses everything (the licence cannot be checked).
        public static string YoutubeApiKey => _youtubeApiKey ??= LoadYoutubeApiKey();
        private static string? _youtubeApiKey;
        private static string LoadYoutubeApiKey()
        {
            string? env = Environment.GetEnvironmentVariable("YOUTUBE_API_KEY");
            if (!string.IsNullOrWhiteSpace(env)) return env.Trim();
            try
            {
                string path = Path.Combine(Environment.CurrentDirectory, "Data", "youtube_api_key.txt");
                if (File.Exists(path))
                    foreach (var raw in File.ReadAllLines(path))
                    {
                        var line = raw.Trim();
                        if (line.Length > 0 && !line.StartsWith("#")) return line;
                    }
            }
            catch (Exception ex) { Console.WriteLine($"[youtube] could not read Data/youtube_api_key.txt: {ex.Message}"); }
            return "";
        }
        public static string YtDlpPath = Environment.GetEnvironmentVariable("CAMPUS_YTDLP") ?? "yt-dlp";
        public static string YoutubeApiBase = Environment.GetEnvironmentVariable("CAMPUS_YT_API_BASE") ?? "https://www.googleapis.com";   // overridden only by tests
        public static int  YoutubeFetchTtlDays    = 3;                       // a fetched video is deleted after this many days
        public static int  YoutubeFetchMaxPerHour = 6;                       // per admin account
        public static int  YoutubeFetchMaxSeconds = 20 * 60;                 // longest video accepted
        public static long YoutubeFetchMaxBytes   = 300L * 1024 * 1024;      // biggest file accepted

