        public static bool OriginLock = true;

        // Escalation in TrafficGuardMiddleware: an address that keeps being rate-limited (it ignores Retry-After, i.e. a bot) is cut off
        // for a while WITHOUT any more work per request. A normal client that backs off after a 429 never gets near this.
        public static int AbuseStrikesToBlock   = 150;   // rejected requests ...
        public static int AbuseStrikeWindowSeconds = 60; // ... inside this many seconds
        public static int AbuseBlockMinutes     = 10;    // how long the address stays cut off

