        //         IsleOfLostSkulls  -> LostSkullsGold  (100)
        //         LaserTag          -> LaserTagTickets (1)
        //      Any other room mints nothing. Rec Center Tokens are NEVER grantable here (server/admin only).
        //   3. Anti-farm (BalanceGuard): a 1-minute rate limit per player (a glitchy double-fire
        //      within seconds just doesn't go through - the player is NOT punished), plus a
        //      long-session cap that denies awards to someone parked in one instance forever.
        public static bool BalanceGuardEnabled = true;

        // Rate limit: at most one currency award per player per this many seconds. A second award
