        // -----------------------------
        // Server Configs
        // -----------------------------
        // ----------------------------------------------------------
        // Request logging  --  THE CAUSE OF GENERAL SLOWNESS
        // ----------------------------------------------------------
        // When true, every request runs through RequestResponseLoggingMiddleware,
        // which does two expensive things per request:
        //
        //   1. Buffers the ENTIRE response into a MemoryStream, so nothing reaches
        //      the client until the handler has fully finished.
        //   2. Emits several Console.WriteLine calls. Console output in .NET is
        //      globally synchronised, and on a systemd unit stdout is a pipe to
        //      journald - a blocking syscall. Every concurrent request therefore
        //      serialises on one lock.
        //
        // Measured from a real log grab: ~175 lines/second, i.e. `journalctl -n 4000`
        // covered only 23 SECONDS. That volume is why chat appears not to send and
        // why everything feels delayed - requests are queueing behind the console
        // lock, not doing real work.
        //
        // Leave FALSE for normal play. Set true only while actively diagnosing, and
        // remember that turning it on is itself a large slowdown. Toggling this
        // cannot change a single response byte - it only controls logging.
        public static bool VerboseRequestLogging = false;

        public static bool AllowAnyVersion = true; // versioncheck api
        public static bool LogMessagesFromSanitize = true; 
