        // obscured (tamper-checked) values, and a level unreachable from its XP reads as
        // memory tampering - it reports Hile Type=Obscured and drops to the dorm with error
        // 385120. See Progress.GetPlayerLevel.
        //
        // REVERT: set this to false to send stored Level and XP verbatim, as before.
        public static bool EnforceLevelXpConsistency = true;

