        // it only when that SHA-256 is the patch the launcher serves (Data/Launcher/patch/latest.json),
        // so uploading a new patch retires every older one. Quest (Oculus) logins are never checked.
        // This is only the FALLBACK: each patch release has its own key, uploaded next to the DLL as
        // Data/Launcher/patch/<sha256>.key (ReleaseGame.bat / release_app.py newkey).
        public static string PatchProofKey =
            Environment.GetEnvironmentVariable("CAMPUS_PATCH_PROOF_KEY") ?? "REDACTED";
        // A developer's OWN copy of the server (started with CAMPUS_LOCAL_DEV=1) has no uploaded patch / launcher / Steam
        // whitelist to compare with, so the launcher's "Dev" channel (the game talks to localhost) would be refused at login by every
        // gate. With this set the three gates are off and patch proofs are accepted. NEVER set it on the live server.
        public static readonly bool LocalDev = Environment.GetEnvironmentVariable("CAMPUS_LOCAL_DEV") == "1";
        // Which host name shows what (Middleware/HostRoutingMiddleware.cs): the website only on camprec.net, the admin panel only on
