        // host (admin.camprec.net) behind the admin login + dev token, and the list is ignored whatever the file says. true = honour it again.
        public static bool AdminIpAllowlistEnabled = false;

        public static bool RequirePatchAtLogin = !LocalDev;      // the kill switch: false = log only
        public static int PatchProofMinutes = 10;           // how long one proof lets logins through
        // How far a player's PC clock may be from ours before the patch / launcher-launch proof is refused
        // ("clock off by more than 5 minutes" -> error code 3). The proof's freshness is judged by when the
        // server RECEIVED it (PatchProofMinutes), so the signed timestamp only has to stop an ancient proof
        // being replayed; it was 5/10 minutes, which locked out players whose Windows clock had drifted
        // (2026-10-06: a UK player, steam ...5089). A day covers any drift short of a wrong date.
        public static int ProofMaxSkewSeconds = 24 * 3600;

        // Separate from the patch gate above: proves the LAUNCHER started the game. The launcher
        // mints an HMAC token with its own per-build key and passes it to the game via the
