        // key from Data/Launcher/app/<sha>.launchkey (release_app.py newlaunchkey writes it).
        public static string LauncherLaunchKey =
            Environment.GetEnvironmentVariable("CAMPUS_LAUNCHER_LAUNCH_KEY") ?? "REDACTED";
        // When ON (and this is a Steam login): a legit patch proof WITHOUT a fresh launcher-launch
        // proof means someone ran a current patch outside the launcher. The server removes the
        // player's Steam id from the normal-player whitelist (LauncherPlayers) and refuses this
        // login. They have to run Campus through the launcher to be re-whitelisted. Quest/Meta
        // and refresh_token are never affected.
        public static bool RequireLauncherLaunch = !LocalDev;    // kill switch mirroring RequirePatchAtLogin

        // The admin panel is browser-only (no DLL), so it is exempt from the patch gate - which
        // means it is reachable by anyone. This is a SEPARATE web token that gates the whole admin
        // surface: you must enter it at /admin/gate before you can see the panel or its login. Keep
        // it secret and strong; it is the "you must know the password to even reach admin" layer,
        // on top of the per-account dev login.
        public static string AdminWebToken = "REDACTED";

